SELECT orc.* FROM t_biam_oauth2_registered_client orc


        AND orc.authorization_grant_type = #{inputDto.authorizationGrantType}


        AND orc.client_id = #{inputDto.clientId}


        AND LOWER(orc.client_name) LIKE LOWER(CONCAT('%', #{inputDto.clientName}, '%'))


        AND orc.status = #{inputDto.status}


        AND orc.update_time > #{inputDto.updateStartTime}


        AND orc.update_time  <  #{inputDto.updateEndTime}


        AND orc.create_by IN

            #{item}



        AND orc.update_by IN

            #{item}



        AND orc.create_time > #{inputDto.createStartTime}


        AND orc.create_time  <  #{inputDto.createEndTime}


ORDER BY orc.create_time DESC
